import React, { useEffect, useRef, useState } from 'react';
import { Video } from 'lucide-react';
import './LiveChat.css';

const LiveChat = () => {
  const [socket, setSocket] = useState(null);
  const [chatStarted, setChatStarted] = useState(false);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const chatEndRef = useRef(null);

  useEffect(() => {
    if (chatStarted && !socket) {
      const ws = new WebSocket('ws://localhost:8000/ws/voicechat');

      ws.onopen = () => {
        console.log('WebSocket connected');
      };

      ws.onmessage = (event) => {
        const msg = JSON.parse(event.data);
        if (msg.type === 'agent_text_partial' || msg.type === 'agent_text_final') {
          setMessages(prev => {
            const last = prev[prev.length - 1];
            if (last && last.sender === 'bot' && msg.type === 'agent_text_partial') {
              const updated = [...prev.slice(0, -1), { ...last, text: last.text + msg.text }];
              return updated;
            } else {
              if (msg.type === 'agent_text_final') speakText(msg.text);
              return [...prev, { sender: 'bot', text: msg.text }];
            }
          });
        } else if (msg.type === 'user_text_partial') {
          // Optional: handle partial user text
        }
      };

      ws.onclose = () => {
        console.log('WebSocket disconnected');
        setSocket(null);
        setChatStarted(false);
      };

      setSocket(ws);
    }
  }, [chatStarted]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = () => {
    if (!input.trim() || !socket) return;
    const userMessage = input.trim();
    setMessages(prev => [...prev, { sender: 'user', text: userMessage }]);
    socket.send(JSON.stringify({ type: 'asr_end', text: userMessage }));
    setInput('');
  };

  const speakText = (text) => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-IN';
    window.speechSynthesis.speak(utterance);
  };

  return (
    <div className="livechat-container">
      <h1><Video className="icon" /> Live Voice Chat Assistant</h1>
      <p className="subtitle">Talk to your farming assistant in real time!</p>

      <div className="chat-box">
        {messages.map((msg, i) => (
          <div key={i} className={`chat-msg ${msg.sender}`}>
            <span>{msg.text}</span>
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>

      <div className="chat-input-row">
        <input
          type="text"
          placeholder="Type your message..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
        />
        <button onClick={sendMessage}>Send</button>
      </div>

      {!chatStarted && (
        <button className="start-btn" onClick={() => setChatStarted(true)}>
          <Video /> Start Live Chat
        </button>
      )}
    </div>
  );
};

export default LiveChat;
